import{d as s,C as n,o as g,c as h,E as a,a3 as i}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"无妄卦","description":"第二十五卦·天雷无妄——天下雷行，物与无妄。无妄不是无为，是「为」先被「时」校准过；眚不是天降之灾，是心生执念之后视野失真。","frontmatter":{"title":"无妄卦","description":"第二十五卦·天雷无妄——天下雷行，物与无妄。无妄不是无为，是「为」先被「时」校准过；眚不是天降之灾，是心生执念之后视野失真。","category":"hexagram","aliases":["无妄","天雷无妄"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/25-tianleiwuwang.md","filePath":"yijing/hexagrams/25-tianleiwuwang.md","lastUpdated":1789714390000}'),p={name:"yijing/hexagrams/25-tianleiwuwang.md"},b=s({...p,setup(u){const o=[{id:"wuwang",term:"无妄",pinyin:"wú wàng",meaning:"不是「无为」，是「为」先被「时」校准过。妄为心生执念、私欲、强求。"},{id:"sheng",term:"眚",pinyin:"shěng",meaning:"字形从目从生，眼生翳障。不是外部降临的灾祸，而是心生执念导致视野失真、从而引发的必然过失。",context:"与乾卦上九「亢龙有悔」的「悔」相对：悔是知道自己偏了，眚是连自己偏没偏都已看不清。"},{id:"zi",term:"菑",pinyin:"zī",meaning:"初耕田、开荒。一说一年之田曰菑。"},{id:"she",term:"畲",pinyin:"shē",meaning:"熟田；一说耕作三年之田曰畲。"},{id:"genghuo",term:"不耕获",pinyin:"bù gēng huò",meaning:"耕种而不图收获。六二以此言「为」而无所算计。"},{id:"feizheng",term:"匪正",pinyin:"fěi zhèng",meaning:"不正、偏离正道。匪即非。"},{id:"maodui",term:"茂对时",pinyin:"mào duì shí",meaning:"茂即努力、勤勉；勉力顺应天时。象传「先王以茂对时育万物」。"},{id:"dezhi",term:"得志",pinyin:"dé zhì",meaning:"志得其所——不是「达成目标」，而是出发点与最真的心志对齐。"},{id:"wuyao",term:"勿药",pinyin:"wù yào",meaning:"不用药、不去试药自证。"},{id:"guyouzhi",term:"固有之",pinyin:"gù yǒu zhī",meaning:"本来就具备的。象传「可贞无咎，固有之也」。"},{id:"jiu",term:"咎",pinyin:"jiù",meaning:"灾祸、罪过。"},{id:"you",term:"攸",pinyin:"yōu",meaning:"所、往。「不利有攸往」即不宜有所往。"}],e=[{position:"初九",type:"yang",text:"无妄，往吉。",xiang:"无妄之往，得志也。",textModern:"出发时心无妄念，前行则吉。",xiangModern:"无妄而往，是志得其所。"},{position:"六二",type:"yin",text:"不耕获，不菑畲，则利有攸往。",xiang:"不耕获，未富也。",textModern:"耕种不图收获，开荒不图新田，如此则利于前行。",xiangModern:"不图收获，所以未把富放在心上。"},{position:"六三",type:"yin",text:"无妄之灾，或系之牛，行人之得，邑人之灾。",xiang:"行人得牛，邑人灾也。",textModern:"没有做错什么却招来灾祸：有人把牛系在那里，过路的人牵走了，账却算在村人头上。",xiangModern:"过路人得了牛，村人却因此受灾。"},{position:"九四",type:"yang",text:"可贞，无咎。",xiang:"可贞无咎，固有之也。",textModern:"可以持守正道，便没有灾祸。",xiangModern:"守正而无咎，是因为这份能力本来就具备。"},{position:"九五",type:"yang",text:"无妄之疾，勿药有喜。",xiang:"无妄之药，不可试也。",textModern:"无端生病，不必用药，自会好转。",xiangModern:"无妄之药，是不可以去试的。"},{position:"上九",type:"yang",text:"无妄，行有眚，无攸利。",xiang:"无妄之行，穷之灾也。",textModern:"即便起点无妄，走到这里若还要妄动，便生遮蔽，无所利。",xiangModern:"无妄而行，是穷极处的灾。"}];return(m,t)=>{const r=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),d=n("DaoKeywordCards");return g(),h("div",null,[a(r,{name:"无妄",fullName:"天雷无妄",upper:"☰",lower:"☳",guaCi:"无妄，元亨利贞。其匪正有眚，不利有攸往。",pinyin:["wú","wàng"],element:"木",direction:"东南",insight:"天下雷行，万物各得其本然。无妄不是无为，是先把「为」对准「时」——先有茂对时的真实作为，才谈得上自然无为的结果。",guaSlug:"25tianleiwuwang",lines:e}),t[0]||(t[0]=i('<h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>无妄，刚自外来而为主于内，动而健，刚中而应。大亨以正，天之命也。其匪正有眚，不利有攸往。无妄之往，何之矣。天命不祐，行矣哉。</p><p>逐句释义：</p><ul><li><strong>刚自外来而为主于内</strong> —— 乾之刚（外卦）自外来，主导内卦震的动。动的主宰不在自身安排，而在那道自外而来的刚。</li><li><strong>动而健</strong> —— 下卦震为动，上卦乾为健：动得刚健，不是躁动。</li><li><strong>刚中而应</strong> —— 九五刚而居中，与六二相应。</li><li><strong>大亨以正，天之命也</strong> —— 真正的顺畅通达，来自「正」这个根基；这是天命本身的规律，不是人力求来的。</li><li><strong>其匪正有眚，不利有攸往</strong> —— 一旦偏离正道，便生遮蔽，不宜再往前行动。</li><li><strong>无妄之往，何之矣；天命不祐，行矣哉</strong> —— 若已失正，则无妄之往还能往哪里去？天命不佑，如何能行。</li></ul><blockquote><p><strong>正为根</strong>：无妄的「亨」不是运气好，是「正」这个根基在托着。</p></blockquote><h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>天下雷行，物与无妄。先王以茂对时育万物。</p><p>天下雷声运行，万物与之相应而各得其本然——这是无妄之象。先王由此悟到：<strong>茂对时，育万物</strong>。</p><p><strong>茂</strong>是努力、勤勉。这里有一条不能颠倒的顺序：<strong>先有「茂对时」的真实作为，才谈得上「自然无为」的结果。</strong> 反过来，拿「顺其自然」「无为」这类高级词汇掩盖自己根本没有「茂对时」的懒惰或算计，本身就是一种更隐蔽的「眚」。</p><blockquote><p><strong>顺序哲学</strong>：无为是作为之后的结果，不是不作为的借口。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',11)),a(l,{element:"木",guaSlug:"25tianleiwuwang",glossary:o,items:e}),t[1]||(t[1]=i('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><p>下三爻（震）是<strong>动的三重考验</strong>：往而吉（初九）、为而不图（六二）、动极生灾（六三）；上三爻（乾）是<strong>贞的三重考验</strong>：守正（九四）、不自证（九五）、物极而蔽（上九）。</p><h3 id="初九-·-无妄-往吉" tabindex="-1">初九 · 无妄，往吉 <a class="header-anchor" href="#初九-·-无妄-往吉" aria-label="Permalink to &quot;初九 · 无妄，往吉&quot;">​</a></h3><ul><li>阳居阳位，得正，处震之初</li><li>出发时心无妄念，前行则吉；小象「得志也」</li></ul><p>「得志」在这里不是达成目标，而是<strong>出发点与最真的心志对齐</strong>。真正的「得鱼忘筏」，不是为了证明自己悟透了，而是不再需要「有用 / 无用」的标签来定义行为的价值。</p><blockquote><p>吉不在结果，在出发的那一刻就已经对上了。</p></blockquote><h3 id="六二-·-不耕获-不菑畲-则利有攸往" tabindex="-1">六二 · 不耕获，不菑畲，则利有攸往 <a class="header-anchor" href="#六二-·-不耕获-不菑畲-则利有攸往" aria-label="Permalink to &quot;六二 · 不耕获，不菑畲，则利有攸往&quot;">​</a></h3><ul><li>阴居阴位，<strong>中且正</strong>，是下卦震的主位，但离主导（九五）尚远</li><li>耕种不图收获、开荒不图新田，如此则利于前行；小象「未富也」</li></ul><p>这里的关口很细：如果「忘掉目的」是为了「更好地达成目的」，那依然是一种算计。真正的「不耕获」，是连「为了达成目的」这个念头都没有，是本然的、不做作的自然流露。</p><blockquote><p>为而不图，不是手段上的谦让，是根本就没把图放在心里。</p></blockquote><h3 id="六三-·-无妄之灾" tabindex="-1">六三 · 无妄之灾 <a class="header-anchor" href="#六三-·-无妄之灾" aria-label="Permalink to &quot;六三 · 无妄之灾&quot;">​</a></h3><ul><li>阴居阳位，不中不正，卡在震卦最顶端——看似最接近乾天，实则最不稳</li><li>爻辞：或系之牛，行人之得，邑人之灾</li></ul><p>这不是道德判断，是<strong>处境结构性地容易被卷入</strong>：空间上的错觉（看似接近，实为幻觉）让偶发之事被强行联系、归结在一起。圣人不给解法，只客观陈述这一处境的必然性；破局的关键不在六三内部，而在于能否撑到九四。</p><blockquote><p>灾祸的降临，不是因为谁的道德有问题，是因为谁站的位置天然更容易被卷进去。</p></blockquote><h3 id="九四-·-可贞-无咎" tabindex="-1">九四 · 可贞，无咎 <a class="header-anchor" href="#九四-·-可贞-无咎" aria-label="Permalink to &quot;九四 · 可贞，无咎&quot;">​</a></h3><ul><li>阳居阴位，本身不当位，但已脱离震的动荡，正式进入乾的刚健笃实</li><li>可以持守正道，便没有灾祸；小象「固有之也」</li></ul><p><strong>贞与躺平不作为的区别</strong>：躺平是回避；贞是清楚自己站的这一步是对的，所以不需要靠「出击」去证明什么——守本身就是一种极其笃定的「作为」。而象传说「固有之也」：这份守得住的能力，不是这一刻突然冒出来的，是本来就有的。</p><blockquote><p>守，不是没有动；是不需要用动来证明。</p></blockquote><h3 id="九五-·-无妄之疾-勿药有喜" tabindex="-1">九五 · 无妄之疾，勿药有喜 <a class="header-anchor" href="#九五-·-无妄之疾-勿药有喜" aria-label="Permalink to &quot;九五 · 无妄之疾，勿药有喜&quot;">​</a></h3><ul><li>阳居阳位，中且正，居君位</li><li>无端生病，不必用药，自会好转；小象「不可试也」</li></ul><p>疾是真实存在的、外来的、无端的，<strong>不是伪装的祝福</strong>。「勿药」不是因为病是假的，而是因为「吃药 / 自证」这个动作本身，就是在怀疑自己那份本来无妄的根基。</p><blockquote><p>一旦去试药，就已经在怀疑那份本来无妄的根基。</p></blockquote><h3 id="上九-·-无妄-行有眚-无攸利" tabindex="-1">上九 · 无妄，行有眚，无攸利 <a class="header-anchor" href="#上九-·-无妄-行有眚-无攸利" aria-label="Permalink to &quot;上九 · 无妄，行有眚，无攸利&quot;">​</a></h3><ul><li>阳居阴位，不中不正，又处卦之极</li><li>即便起点无妄，走到这里若还要妄动，便生遮蔽，无所利；小象「穷之灾也」</li></ul><p>与乾卦「亢龙有悔」的对照，是这一爻的关键：</p><table tabindex="0"><thead><tr><th></th><th>状态</th><th>差别</th></tr></thead><tbody><tr><td>悔（亢龙有悔）</td><td>知道自己偏了</td><td>认知尚未被完全遮蔽</td></tr><tr><td>眚（行有眚）</td><td>连「自己偏没偏」都已看不清</td><td>处境已到「极」，却不自知</td></tr></tbody></table><p>不是无妄本身的错，是身处「极」这一处境却不自知——忽略处境、只顾坚持自我，早已埋下失败的引子。</p><blockquote><p>亢龙有悔尚有一线自知；行有眚，是连自知都没了。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',29)),a(d,{title:"字词释义",items:[{term:"无妄",pinyin:["wú","wàng"],meaning:"不是「无为」，是「为」先被「时」校准过。妄为心生执念、私欲、强求。"},{term:"眚",pinyin:["shěng"],meaning:"字形从目从生，眼生翳障。不是外部降临的灾祸，而是心生执念导致视野失真、从而引发的必然过失。"},{term:"菑",pinyin:["zī"],meaning:"初耕田、开荒。一说一年之田曰菑。"},{term:"畲",pinyin:["shē"],meaning:"熟田；一说耕作三年之田曰畲。"},{term:"不耕获",pinyin:["bù","gēng","huò"],meaning:"耕种而不图收获。六二以此言「为」而无所算计。"},{term:"匪正",pinyin:["fěi","zhèng"],meaning:"不正、偏离正道。匪即非。「其匪正有眚」。"},{term:"茂对时",pinyin:["mào","duì","shí"],meaning:"茂即努力、勤勉；勉力顺应天时。象传「先王以茂对时育万物」。"},{term:"得志",pinyin:["dé","zhì"],meaning:"志得其所——不是「达成目标」，而是出发点与最真的心志对齐。"},{term:"勿药",pinyin:["wù","yào"],meaning:"不用药、不去试药自证。九五「无妄之疾，勿药有喜」。"},{term:"固有之",pinyin:["gù","yǒu","zhī"],meaning:"本来就具备的。象传「可贞无咎，固有之也」。"},{term:"天命不祐",pinyin:["tiān","mìng","bù","yòu"],meaning:"天命不保佑。彖传「天命不祐，行矣哉」。"},{term:"咎",pinyin:["jiù"],meaning:"灾祸、罪过。"},{term:"攸",pinyin:["yōu"],meaning:"所、往。「不利有攸往」即不宜有所往。"}]}),t[2]||(t[2]=i('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>无妄卦讲的是<strong>不妄为</strong>。乾上震下，天下雷行——雷动于天下，万物与之相应，各得其本然。「无妄」拆开是「无」加「妄」：<strong>妄</strong>是心生执念、私欲、强求；<strong>无妄</strong>不是「无为」，是「为」先被「时」校准过。</p><p>卦辞「元亨利贞。其匪正有眚，不利有攸往」立了规矩：起点纯正则大为顺畅、利于守正；一旦偏离正道，便生遮蔽，不宜再往前动。</p><p>而「眚」字是这一卦的题眼：字形从目从生，是眼生翳障——<strong>不是外部降临的灾祸，是心生执念导致视野失真，从而引发的必然过失。</strong></p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>因为它纠正两个默认反应。</p><p>一是把「无妄」读成「无为」。象传「先王以茂对时育万物」指出了一条不能颠倒的顺序：<strong>先有「茂对时」的真实作为，才谈得上「自然无为」的结果。</strong> 用「顺其自然」「无为」掩盖不作为，那是更隐蔽的眚——而且是双重遮蔽：一层是主观私欲带来的认知偏差，一层是引经据典的遮蔽。</p><p>二是把「灾」读成道德结果。六三「无妄之灾」说的不是谁品德有问题，而是<strong>处境结构性地容易被卷入</strong>；九五「无妄之疾」说的也不是福报伪装，而是真实的、外来的、无端的事。看清这一层，才不至于在无辜受挫时先向自己问罪。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li><strong>先茂对时</strong>：把「为」对准「时」再动，而不是拿「无为」当挡箭牌（象传）</li><li><strong>为而不图</strong>：做的时候不必揣着「为了更好的结果」这个算计，本然流露才是无妄（六二）</li><li><strong>看清位置</strong>：有些灾是位置带来的，先辨清自己站在哪一种位置上，别忙着自我归罪（六三）</li><li><strong>守就是作为</strong>：贞不是躺平等结果，是清楚这一步是对的，因此不必靠出击证明（九四）</li><li><strong>不自证</strong>：遇到无端之疾，不必去「试药」自证清白——一试就已经在怀疑根基（九五）</li><li><strong>极处要自知</strong>：到了「极」还不自知，就会从「悔」滑向「眚」（上九）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>无妄六爻的结构总览：</p><table tabindex="0"><thead><tr><th>爻位</th><th>阴阳与位</th><th>中正</th><th>所属卦</th><th>核心主题</th><th>人物锚点</th></tr></thead><tbody><tr><td>初九</td><td>阳居阳</td><td>正</td><td>震</td><td>往吉 · 初心</td><td>诸葛亮</td></tr><tr><td>六二</td><td>阴居阴</td><td>中且正</td><td>震</td><td>不图收获</td><td>陶渊明</td></tr><tr><td>六三</td><td>阴居阳</td><td>不中不正</td><td>震</td><td>无妄之灾</td><td>扶苏</td></tr><tr><td>九四</td><td>阳居阴</td><td>不当位</td><td>乾</td><td>可贞无咎</td><td>郭子仪</td></tr><tr><td>九五</td><td>阳居阳</td><td>中且正（君位）</td><td>乾</td><td>勿药有喜</td><td>岳飞</td></tr><tr><td>上九</td><td>阳居阴</td><td>不中不正（极）</td><td>乾</td><td>行有眚</td><td>王莽</td></tr></tbody></table><p><strong>动与贞的转换</strong>：</p><ul><li>初九、六二、六三 —— 动的三重考验：往、为而不图而往、动极生灾</li><li>九四、九五、上九 —— 贞的三重考验：守正、不自证、物极而蔽</li></ul><p>核心洞见：</p><ol><li><strong>眚的本质</strong>——无妄卦讲的不是灾祸从天降，而是心生执念导致视野失真，从而走向灾祸</li><li><strong>无妄的真义</strong>——不是无为，是「为」先对准「时」；茂对时是努力，但努力的方向被规律校准</li><li><strong>防范哲学遮蔽</strong>——先有「茂对时」的真实作为，才谈得上「自然无为」的结果，顺序不能颠倒</li><li><strong>无妄之灾的结构性</strong>——灾祸降临不是因为谁的道德有问题，是因为谁站的位置天然更容易被卷进去。不是宿命论，是提醒看清自己此刻站的是哪一种位置</li><li><strong>贞的境界</strong>——贞不是「什么都不做去等结果」，是把一路积累下来的端正稳稳守住，不因外面的风浪而摇摆；贞本身就是一种极其笃定的「作为」</li><li><strong>勿药有喜的真义</strong>——不是说疾病是伪装的好事，是说真正的贞不需要靠「治好」来自证清白</li><li><strong>悔与眚的分野</strong>——悔是知道自己偏了，眚是连自己偏没偏都已经看不清</li><li><strong>眚的渐变</strong>——眚不是一次性的错误，是一个从「清醒」滑向「遮蔽」的渐变过程；无妄六爻恰好标出了这条滑坡上每一个关键的岔路口</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>这一卦最难的地方，不在「怎么做到无妄」，而在<strong>看清自己此刻处在哪一层</strong>。</p><p>真正的「忘掉过程」，不是为了证明自己悟透了，而是不再需要「有用 / 无用」的标签来定义行为。承认普通，比伪装深刻更接近无妄。</p><p>策略性的不动与真正的不为所动，是两种东西：前者用不动去换取一个结果，后者是压根没生出念头。而更难的是——看清自己此刻处于哪一层之后，<strong>不急着去表演那个更高的层次，只是如实承认</strong>。这大概才是无妄真正能落地的样子。</p><p>至于「眚」，我把它读成一条滑坡而不是一次失足：它从清醒一点点滑向遮蔽，每一爻都是这条滑坡上的一个岔路口。所以真正要守的，不是「我从不犯错」，而是「我还看得见自己有没有偏」。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：<a href="/Dao/yijing/hexagrams/01-qianweitian">乾（第一卦）</a>、<a href="/Dao/yijing/hexagrams/24-dileifu">复（第二十四卦）</a>、<a href="/Dao/yijing/hexagrams/26-shantiandaxu">大畜（第二十六卦）</a>、<a href="/Dao/yijing/hexagrams/51-zhenweilei">震（第五十一卦）</a></li><li>序卦：「复则不妄矣，故受之以无妄」——复是回归正道，无妄是不再偏离；「有无妄，然后可畜，故受之以大畜」——先有无妄之正，才谈得上蓄养</li><li>与乾卦上九「亢龙有悔」的对照：<strong>悔是知道自己偏了，眚是连自己偏没偏都已看不清</strong>——这是两卦最本质的一处分野</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/bian-yi">变易</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',25))])}}});export{y as __pageData,b as default};
